Object.assign(window.FIGS,{"intego::l1": [{"s": "data:image/jpeg;base64,", "c": "Şekil 1: Intego CS dental tedavi ünitesi — A: Hasta koltuğu, B: Baş desteği, C: Pedal, D: Dişçi ünitesi (CS kamçı kollu), E: Asistan ünitesi, F: Su ünitesi, G: Güç şalteri"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 2: Çift mafsallı baş desteği — A: Yastık, B: Mafsal, C: Kilit, D: Kızak"}], "intego::l2": [{"s": "data:image/jpeg;base64,", "c": "Şekil 3: Pedal bileşenleri — A: Ayak pedalı, B: Sol tuş (S/Sprey), C: İmleç kumandası (çapraz şalter), D: Sağ tuş (0/Chipblower), E: Konumlandırma braketi, F: Bağlantı kablosu"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 3b: Pedal C+ tüm fonksiyonları — aletler yerindeyken ve alet alındığında tuş işlevleri"}], "intego::l3": [{"s": "data:image/jpeg;base64,", "c": "Şekil 4: EasyPad kontrol paneli — A: Gösterge, B: Durum göstergeleri, C: Sabit tuşlar, D: Favoriler tuş alanı"}], "intego::l4": [{"s": "data:image/jpeg;base64,", "c": "Şekil 5a: Asistan ünitesi Kompakt — A: Aletler için koyma yeri (1-4, soldan sağa), B: Kullanıcı arayüzü, C: Tutamak"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 5b: Asistan ünitesi sabit tuşları — S, 0, bardak dolumu, kapsamlı yıkama, tedavi lambası, Fn"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 6: Su ünitesi (Kompakt) — A: Manüel döndürülebilen kreşuar, B: Bardak doldurucu, C: Temiz su şişesi bağlantısı, D: Emme hortumu temizliği girişi, E: Emme hortumu bağlantısı, F: Bakım kapağı, G: Merkezi emiş süzgeci"}], "intego::l5": [{"s": "data:image/jpeg;base64,", "c": "Şekil 7: Tedavi lambası kumanda tuşları — art arda basışla Açık → Kompozit → Kapalı"}], "intego::l12": [{"s": "data:image/jpeg;base64,", "c": "Şekil 8: Kompakt su ünitesi — emme hortumu temizliği girişi (D) kreşuarın altındadır"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 9: Günlük — emme hortumlarının temizlik adaptörleri (A) ile temizlenmesi ve su yollarının yıkanması (Dentsply Sirona bakım planı)"}], "intego::l13": [{"s": "data:image/jpeg;base64,", "c": "Adım 1: Setup menüsüne giriş — Favori 2 / Setup tuşunu >2 sn basılı tutun"}, {"s": "data:image/jpeg;base64,", "c": "Adım 2: Kısa basışlarla 'Sr' parametresine gelin"}, {"s": "data:image/jpeg;base64,", "c": "Adım 3: 'Sr' ekranında Setup tuşunu >2 sn tutun — ekran 'Sr 366' olur"}, {"s": "data:image/jpeg;base64,", "c": "Adım 4: A/B (sola çalışma) tuşu ile çıkış"}], "yangin::l1": [{"s": "data:image/jpeg;base64,", "c": "Şekil 1: Yangın tüpünün ana bileşenleri — emniyet pimi, tetik/kol (sıkma kolu), taşıma sapı, basınç göstergesi (manometre), hortum, nozul (ağızlık), gövde (silindir) ve etiket, taban halkası"}], "yangin::l3": [{"s": "data:image/jpeg;base64,", "c": "Şekil 2: Yangın tüpü kullanım adımları (PASS): 1 Pimi çek → 2 Tabana nişan al → 3 Tetiği sık → 4 Yandan yana tara"}], "yangin::l6": [{"s": "data:image/jpeg;base64,", "c": "Şekil 3: Kat planında işaretli yangın tüpü konumları — 1: Personel Girişi / Sterilizasyon Koridoru, 2: Ana Giriş / Klinik Koridoru"}], "siman::l1": [{"s": "data:image/jpeg;base64,", "c": "Klinikteki yapıştırıcılardan: Calibra Universal self-adeziv rezin siman şırıngası"}], "siman::l4": [{"s": "data:image/jpeg;base64,", "c": "Panavia V5 ile zirkonya kron simantasyonu — 1) alümina ile kumlama, 2) Ceramic Primer Plus, 3) Tooth Primer (20 sn), 4) siman + yerleştirme, 5) fazla siman temizliği (tack-cure veya fırça), 6) 3 dk izolasyon / ışıkla kür. (Kaynak görsel; etiketler İngilizcedir.)"}], "siman::l5": [{"s": "data:image/jpeg;base64,", "c": "RelyX Unicem dağıtıcıları — solda kollu Clicker (elde karışım), sağda Automix şırınga. Klinikte Clicker kullanılır."}, {"s": "data:image/jpeg;base64,", "c": "Clicker sırası — pastaları pede bırak → spatül ile karıştır → çıkış deliklerini sil → kapağı 'klik' sesiyle geri tak"}], "siman::l7": [{"s": "data:image/jpeg;base64,", "c": "Bifix QM QuickMix şırınga ve karıştırma ucu — malzeme uç içinde otomatik karışır"}, {"s": "data:image/jpeg;base64,", "c": "Ceramic Bond (silan) restorasyonun iç yüzeyine fırça ile uygulanır, 60 sn bekletilir"}], "siman::l8": [{"s": "data:image/jpeg;base64,", "c": "Calibra Universal çift hazneli şırıngaya karıştırma ucunun takılması ve simanın restorasyona uygulanması — ucun V-çentiği şırınga flanşındaki V-çentikle hizalanır, renkli kapak 90° çevrilerek sabitlenir"}], "c8::l1": [{"s": "data:image/jpeg;base64,", "c": "Şekil 1: C8⁺ (kamçılı) ana bileşenleri — hasta koltuğu, kamçılı dişhekimi ünitesi, su ünitesi, asistan ünitesi + koltuk kumanda düğmeleri, çalışma lambası, program pozisyonlu ayak pedalı"}], "c8::l3": [{"s": "data:image/jpeg;base64,", "c": "Şekil 2: Günlük kullanım iş akışına genel bakış — sistemi aç → hastayı yerleştir → tedavi et → topla"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 3: Ünite üzerinden ayarlanabilen süre ve yoğunluklar — kreşuar çalkalama (30 sn), bardak dolumu (4 sn), sprey su yoğunluğu (−/+), koltuk program pozisyonları"}], "c8::l4": [{"s": "data:image/jpeg;base64,", "c": "Şekil 4: Program pozisyonlu ayak pedalı — S çalkalama, 0 iniş-biniş, 1 üst çene, 2 alt çene; ortadaki tuşla elle yükselt/alçalt"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 5: Asistan (yan) kumanda paneli — koltuk hareketi, program pozisyonları, su düğmeleri; tuşa 3 sn'den uzun basmak ayarı yeniden programlar, sadece KISA basın"}], "c8::l5": [{"s": "data:image/jpeg;base64,", "c": "Şekil 6: Kamçı kolun doğru ve yanlış kullanımı — kolu geriye itmeyin; alet hortumunu dışarı çekerek 'klik' ile kilitleyin"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 7: SPRAYVIT tuşları ve açma/sökme adımları — sağ tuş SU, sol tuş HAVA, ikisi SPREY; parçalar 135 °C / 3 dk otoklav; 'Click' sesiyle takıp çekerek kontrol edin"}], "c8::l6": [{"s": "data:image/jpeg;base64,", "c": "Şekil 8: Sprey su yoğunluğu döner düğmesi (−/+) — dişhekimi ünitesi ön panelinin altında"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 9: Kreşuar çalkalama (30 sn) ve bardak dolum (4 sn) süresini programlama"}], "c8::l7": [{"s": "data:image/jpeg;base64,", "c": "Şekil 10: Emici ve tükürük ejektörü — emici halka ile açılır (I) / kapatılır (O); ucu damağa/yumuşak dokuya bastırmayın"}], "c8::l8": [{"s": "data:image/jpeg;base64,", "c": "Şekil 11: Haftalık döşeme bakımı — döşeme yüzeyleri onaylı bakım maddesiyle silinir (Dentsply Sirona bakım planı)"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 12: Her hasta arası tüm yüzeylerin silinerek dezenfekte edilmesi (Dentsply Sirona bakım planı)"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 13: Ayak pedalının alttan nemli bezle temizlenmesi — içine su kaçırmayın"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 14: Emici uç O-ringlerinin greslenmesi — termal dezenfeksiyon sonrası ve haftada bir"}], "intego::l7": [{"s": "data:image/jpeg;base64,", "c": "Resmi bakım planı — her hastadan sonra: yüzeyler, tutamaklar, tepsi, kullanıcı arayüzü ve bağlantıların dezenfeksiyonu (Dentsply Sirona bakım planı)"}], "nobel::l1": [{"s": "data:image/jpeg;base64,", "c": "NobelReplace CC Cerrahi Set (Surgery Kit) — dizilmiş tepsi"}], "nobel::l2": [{"s": "data:image/jpeg;base64,", "c": "Şekil 1: NobelReplace CC Cerrahi Set — bölge haritası (1: frez protokolü paneli, 2: başlangıç frezleri, 3: Unigrip anahtar/uzatma/yedek, 4: twist frezler, 5: Dense Bone, 6: yiv açıcı + yön göstergesi, 7: implant taşıma + kemik freni)"}], "siman::l10": [{"s": "data:image/jpeg;base64,", "c": "CLEARFIL DC CORE PLUS otomatik karışan şırınga (solda) ve birlikte kullanılan CLEARFIL Universal Bond Quick adezivi (sağda)"}, {"s": "data:image/jpeg;base64,", "c": "Kısa klinik akış — 1) BOND'u ovalayarak uygula (bekleme yok), 2) hafif hava + paper point ile BOND hareket etmeyene kadar kurut (5 sn+), 3) ışıkla kürle, 4) CLEARFIL DC CORE PLUS ile post simantasyonu ve kor yapımı. (Kaynak görsel; etiketler İngilizcedir.)"}], "rinn::l1": [{"s": "data:image/jpeg;base64,", "c": "XCP renk kodlu fosfor plak ısırma blokları: Ön (mavi) • Arka (sarı) • Isırma (kırmızı) • Endodontik (yeşil)"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 1: XCP tutucusunun ana bileşenleri — fosfor plak (zarf içinde), nişan halkası, ısırma bloğu, gösterge kolu. (Mavi ön tutucu örnektir.) Kaynak: Dentsply Sirona Rinn"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 2: Renk kodu rehberi — her rengin hangi dişlerde kullanıldığı. Kaynak: Dentsply Sirona Rinn Color Guide"}], "rinn::l3": [{"s": "data:image/jpeg;base64,", "c": "Şekil 3: Bölgeye göre reseptör yerleşimi ve merkezi ışın yönü (konumlandırma geometrisi; fosfor plakta kablo yoktur). Kaynak: Dentsply Sirona XCP Konumlandırma Kılavuzu"}], "vs600::l1": [{"s": "data:image/jpeg;base64,", "c": "Dürr VS 600 kombine emiş makinesi"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 1: Sistem bileşenleri — 1: kombine emiş makinesi, 2: kontrol kutusu, 3: bağlantı parçaları seti, 4: emiş hortumu, 5: egzoz hava hortumu, 6: atık su hortumu"}], "vs600::l3": [{"s": "data:image/jpeg;base64,", "c": "Şekil 2: VS 600 koruyucu süzgeç — ① emici hortumu çek, ② süzgeci separatör gövdesinden dışarı çıkar"}], "quattro::l1": [{"s": "data:image/jpeg;base64,", "c": "Dürr Quattro — membran kurutuculu dental kompresör (çift agrega)"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 1: Hava akışı ve ana bileşenler — 1: kompresör agregası, 2: hava emiş filtresi, 3: basınç tankı, 4: kondens tahliye valfi, 6: basınç şalteri, 7: emniyet valfi, 8: manometre, 10: fanlı soğutucu, 11: membran kurutucu, 13: nem göstergesi, 14: ince/virüs-bakteri filtresi, 17: koalesans filtresi. (Şema tek agregalı çizilmiştir; cihazda iki agrega bulunur.)"}], "quattro::l2": [{"s": "data:image/jpeg;base64,", "c": "Şekil 2: Basınç şalteri ve döner açma/kapama şalteri (I AUTO / 0 OFF)"}], "quattro::l3": [{"s": "data:image/jpeg;base64,", "c": "Şekil 3: Membran kurutucu kondens tahliye valfi (alt uç) — kompresör çalışırken ~3 tur gevşetin; iki kurutucunun da valfini boşaltın"}, {"s": "data:image/jpeg;base64,", "c": "Şekil 4: Basınç tankı kondens tahliye valfi"}]});
